use std::future::Future;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard};

use eyre::{Result, bail};

use super::checkpoint::{Draft, Outcome, Store};
use super::journal::JournalEntry;
use super::store::{
