            // it did not: keep the earlier protective checkpoint, which is
            // still what the pending record points at
            (false, Some(previous)) => {
                writer.operation_mut().before = Some(previous.1.clone());
                writer.before = Some(previous);
            }
            (_, None) => {}
        }
